using AlzaProducts.Domain;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace AlzaProducts.Infrastructure.Products;

/// <summary>
/// Maps the Product domain model to the Products table, so the domain itself needs no database attributes
/// </summary>
public sealed class ProductConfiguration : IEntityTypeConfiguration<Product>
{
    public void Configure(EntityTypeBuilder<Product> builder)
    {
        builder.ToTable("Products");

        builder.HasKey(product => product.Id);
        // Ids are assigned by the domain, never generated by the database
        builder.Property(product => product.Id).ValueGeneratedNever();

        builder.Property(product => product.Name)
            .HasMaxLength(Product.NameMaxLength)
            .IsRequired();

        // Stored as the exact text the domain validated, so the same length limit applies
        builder.Property(product => product.ImgUri)
            .HasConversion(uri => uri.OriginalString, value => new Uri(value))
            .HasMaxLength(Product.ImgUriMaxLength)
            .IsRequired();

        builder.Property(product => product.Price).HasPrecision(18, 2);

        builder.Property(product => product.Description).HasMaxLength(Product.DescriptionMaxLength);

        // Lists are sorted by name, then by id; SQL Server adds the clustered key (Id) to every index,
        // so this index covers the whole sort order
        builder.HasIndex(product => product.Name);
    }
}
